import{_ as a,o as s,c as t,a5 as n}from"./chunks/framework.DJo0M80U.js";const b=JSON.parse('{"title":"59. Understanding the Object File","description":"The Little Book of C — 59. Understanding the Object File","frontmatter":{"title":"59. Understanding the Object File","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Compilation and Build"],"description":"The Little Book of C — 59. Understanding the Object File","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":59,"sidebarWeight":59,"lang":"en-US","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File","alternateZh":"/posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File"},"headers":[],"relativePath":"posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File.md","filePath":"posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/06-Compilation and Build/059-Understanding the Object File.md"};function l(o,e,p,d,c,r){return s(),t("div",null,[...e[0]||(e[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/06-编译与构建/059-Understanding the Object File)</p><p>By now, you’ve seen<code>.o</code> files appear in every build step, the intermediate products between source and executable. But what exactly is inside them?</p><p>Object files are the compiler’s way of packaging machine code, symbol tables, and metadata, ready for the linker to assemble into a final program. Understanding object files helps you debug linking errors, inspect performance, and even reverse-engineer compiled code.</p><h4 id="step-1-the-lifecycle-recap" tabindex="-1">Step 1. The Lifecycle Recap <a class="header-anchor" href="#step-1-the-lifecycle-recap" aria-label="Permalink to &quot;Step 1. The Lifecycle Recap&quot;">​</a></h4><p>The compilation pipeline looks like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source.c ──&gt; preprocessor ──&gt; compiler ──&gt; assembler ──&gt; linker</span></span>
<span class="line"><span>     |                           |             |          |</span></span>
<span class="line"><span>     |                        hello.s        hello.o     a.out</span></span></code></pre></div><p>Your<code>.c</code> file becomes a<code>.o</code> file after assembly, but before linking.</p><p>Each<code>.o</code> is self-contained, it knows what it defines, what it needs, and where its code lives in memory.</p><h4 id="step-2-object-file-formats" tabindex="-1">Step 2. Object File Formats <a class="header-anchor" href="#step-2-object-file-formats" aria-label="Permalink to &quot;Step 2. Object File Formats&quot;">​</a></h4><p>Different operating systems use different binary formats:</p><table tabindex="0"><thead><tr><th>OS</th><th>Format</th><th>Typical Extension</th></tr></thead><tbody><tr><td>Linux</td><td>ELF (Executable and Linkable Format)</td><td><code>.o</code>,<code>.so</code>, executable</td></tr><tr><td>macOS</td><td>Mach-O</td><td><code>.o</code>,<code>.dylib</code></td></tr><tr><td>Windows</td><td>COFF/PE</td><td><code>.obj</code>,<code>.dll</code>,<code>.exe</code></td></tr></tbody></table><p>On Linux, ELF dominates, so we’ll use it as our reference.</p><h4 id="step-3-sections-inside-an-object-file" tabindex="-1">Step 3. Sections Inside an Object File <a class="header-anchor" href="#step-3-sections-inside-an-object-file" aria-label="Permalink to &quot;Step 3. Sections Inside an Object File&quot;">​</a></h4><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c -o main.o</span></span>
<span class="line"><span>readelf -S main.o</span></span></code></pre></div><p>You’ll see output like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ 1] .text     PROGBITS  code and functions</span></span>
<span class="line"><span>[ 2] .data     PROGBITS  initialized global variables</span></span>
<span class="line"><span>[ 3] .bss      NOBITS    uninitialized globals</span></span>
<span class="line"><span>[ 4] .rodata   PROGBITS  constants (e.g., string literals)</span></span>
<span class="line"><span>[ 5] .symtab   SYMTAB    symbol table</span></span>
<span class="line"><span>[ 6] .strtab   STRTAB    string table</span></span>
<span class="line"><span>[ 7] .rel.text RELA      relocation info</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Section</th><th>Contents</th></tr></thead><tbody><tr><td><code>.text</code></td><td>Compiled machine code (functions)</td></tr><tr><td><code>.data</code></td><td>Global variables with initial values</td></tr><tr><td><code>.bss</code></td><td>Global variables without initial values</td></tr><tr><td><code>.rodata</code></td><td>Constants,<code>const</code> variables, string literals</td></tr><tr><td><code>.symtab</code></td><td>Symbol table: function and variable metadata</td></tr><tr><td><code>.rel*</code></td><td>Relocation info, how to connect this file to others</td></tr></tbody></table><h4 id="step-4-inspecting-symbols" tabindex="-1">Step 4. Inspecting Symbols <a class="header-anchor" href="#step-4-inspecting-symbols" aria-label="Permalink to &quot;Step 4. Inspecting Symbols&quot;">​</a></h4><p>Every<code>.o</code> file contains symbols that describe its functions and variables. List them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000000000 T main</span></span>
<span class="line"><span>                 U printf</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Symbol</th><th>Meaning</th></tr></thead><tbody><tr><td><code>T</code></td><td>Defined in the text (code) section</td></tr><tr><td><code>U</code></td><td>Undefined, must be provided by another file or library</td></tr><tr><td><code>D</code></td><td>Defined in data section</td></tr><tr><td><code>B</code></td><td>Defined in bss section</td></tr><tr><td><code>R</code></td><td>Defined in read-only data</td></tr><tr><td><code>W</code></td><td>Weak symbol (can be overridden)</td></tr></tbody></table><p>Here,<code>main</code> is defined,<code>printf</code> is undefined, meaning the linker must find it in the C standard library.</p><h4 id="tiny-code-inspecting-a-multi-file-example" tabindex="-1">Tiny Code: Inspecting a Multi-File Example <a class="header-anchor" href="#tiny-code-inspecting-a-multi-file-example" aria-label="Permalink to &quot;Tiny Code: Inspecting a Multi-File Example&quot;">​</a></h4><p>math.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>int mul(int a, int b) { return a * b; }</span></span></code></pre></div><p>main.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int add(int, int);</span></span>
<span class="line"><span>int mul(int, int);</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, add(2, 3) * mul(1, 4));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile but don’t link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c main.c</span></span>
<span class="line"><span>gcc -c math.c</span></span></code></pre></div><p>Inspect:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nm main.o</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>U add</span></span>
<span class="line"><span>U mul</span></span>
<span class="line"><span>U printf</span></span>
<span class="line"><span>T main</span></span></code></pre></div><p><code>U</code> means undefined, the linker must resolve these.</p><p>Now inspect<code>math.o</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T add</span></span>
<span class="line"><span>T mul</span></span></code></pre></div><p>These are definitions that will satisfy the linker.</p><p>Link and inspect the result:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.o math.o -o app</span></span>
<span class="line"><span>nm app | grep add</span></span></code></pre></div><p>Now you’ll see:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000401136 T add</span></span></code></pre></div><p>The linker relocated<code>add()</code> into its final address.</p><h4 id="step-5-symbol-visibility" tabindex="-1">Step 5. Symbol Visibility <a class="header-anchor" href="#step-5-symbol-visibility" aria-label="Permalink to &quot;Step 5. Symbol Visibility&quot;">​</a></h4><p>By default, every function and global variable has external linkage, visible to the linker.</p><p>Use<code>static</code> to limit visibility to the current file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>static int hidden_func(void) { return 42; }</span></span></code></pre></div><p>Now<code>nm</code> will not list it as an exported symbol. This keeps your binary clean and prevents name collisions across files.</p><h4 id="step-6-inspecting-relocations" tabindex="-1">Step 6. Inspecting Relocations <a class="header-anchor" href="#step-6-inspecting-relocations" aria-label="Permalink to &quot;Step 6. Inspecting Relocations&quot;">​</a></h4><p>Object files can’t know final addresses yet, so they store relocation entries: placeholders for addresses that the linker must fill later.</p><p>Check them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>readelf -r main.o</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Relocation section &#39;.rela.text&#39;:</span></span>
<span class="line"><span>0000000000000010 R_X86_64_PC32 printf-0x4</span></span></code></pre></div><p>This tells the linker:</p><p>“When linking, replace this placeholder with the address of<code>printf()</code>.”</p><h4 id="step-7-disassemble-the-code" tabindex="-1">Step 7. Disassemble the Code <a class="header-anchor" href="#step-7-disassemble-the-code" aria-label="Permalink to &quot;Step 7. Disassemble the Code&quot;">​</a></h4><p>You can see the actual machine instructions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>objdump -d main.o</span></span></code></pre></div><p>Output snippet:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0000000000000000 &lt;main&gt;:</span></span>
<span class="line"><span>   0: 55                    push   %rbp</span></span>
<span class="line"><span>   1: 48 89 e5              mov    %rsp,%rbp</span></span>
<span class="line"><span>   4: b8 00 00 00 00        mov    $0x0,%eax</span></span></code></pre></div><p>Each instruction corresponds to compiled C code. This is how you verify optimizations, inspect inlining, or study generated assembly.</p><h4 id="step-8-mixing-object-files" tabindex="-1">Step 8. Mixing Object Files <a class="header-anchor" href="#step-8-mixing-object-files" aria-label="Permalink to &quot;Step 8. Mixing Object Files&quot;">​</a></h4><p>Because<code>.o</code> files contain clear symbol metadata, you can mix object files from different languages, for example, C and assembly.</p><p>sum.s</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.globl sum</span></span>
<span class="line"><span>sum:</span></span>
<span class="line"><span>    addq %rsi, %rdi</span></span>
<span class="line"><span>    movq %rdi, %rax</span></span>
<span class="line"><span>    ret</span></span></code></pre></div><p>Compile and link:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>as sum.s -o sum.o</span></span>
<span class="line"><span>gcc main.c sum.o -o app</span></span></code></pre></div><p>This is how C integrates cleanly with low-level code.</p><h4 id="step-9-object-file-size-and-contents" tabindex="-1">Step 9. Object File Size and Contents <a class="header-anchor" href="#step-9-object-file-size-and-contents" aria-label="Permalink to &quot;Step 9. Object File Size and Contents&quot;">​</a></h4><p>Check file size:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>size main.o</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text    data     bss     dec     hex filename</span></span>
<span class="line"><span>45      4        0       49      31  main.o</span></span></code></pre></div><ul><li><code>text</code>→ code size</li><li><code>data</code>→ initialized global variables</li><li><code>bss</code>→ uninitialized variables</li></ul><h4 id="step-10-tiny-code-investigate-everything" tabindex="-1">Step 10. Tiny Code: Investigate Everything <a class="header-anchor" href="#step-10-tiny-code-investigate-everything" aria-label="Permalink to &quot;Step 10. Tiny Code: Investigate Everything&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -c hello.c -o hello.o</span></span>
<span class="line"><span>readelf -h hello.o          # ELF header</span></span>
<span class="line"><span>readelf -S hello.o          # Sections</span></span>
<span class="line"><span>readelf -s hello.o | head   # Symbol table</span></span>
<span class="line"><span>readelf -r hello.o          # Relocations</span></span>
<span class="line"><span>objdump -d hello.o | head   # Disassembly</span></span></code></pre></div><p>You’ll get a complete low-level view of how your C code looks to the compiler.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Understanding object files helps you:</p><ul><li>Debug linking errors and symbol conflicts</li><li>Inspect compiler optimizations</li><li>Integrate C with assembly</li><li>Build static and shared libraries manually</li><li>See what’s actually inside the binary</li></ul><p>In systems programming, this insight separates code users from code engineers.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Create two<code>.o</code> files that depend on each other and inspect their undefined symbols.</li><li>Use<code>readelf -S</code> to compare<code>.text</code>,<code>.data</code>, and<code>.bss</code> for different programs.</li><li>Add a global variable and see how it appears in<code>.data</code> or<code>.bss</code>.</li><li>Mark a function as<code>static</code> and confirm it disappears from<code>nm</code> output.</li><li>Compile with<code>-O2</code> and observe changes in disassembly with<code>objdump -d</code>.</li></ol><p>Next, you’ll complete Chapter 6 by building your own Makefile-based compilation pipeline from scratch, writing every stage explicitly to transform<code>.c</code> files into<code>.o</code>,<code>.a</code>, and<code>.so</code> artifacts just like a real compiler toolchain.</p>`,86)])])}const u=a(i,[["render",l]]);export{b as __pageData,u as default};
